SELECT id, seat_id, room_id, user_id, book_date, start_time, end_time, status
FROM seat_booking
WHERE seat_id = #{seatId}
AND book_date = #{bookDate}
AND status IN ('BOOKED', 'CHECKED_IN', 'LEAVING')

AND start_time < #{endTime}
AND end_time > #{startTime}
ORDER BY start_time
LIMIT 1

SELECT COUNT(*)
FROM seat_booking
WHERE user_id = #{userId}
AND book_date = #{bookDate}
AND status IN ('BOOKED', 'CHECKED_IN', 'LEAVING')

mapper.update:
UPDATE seat_booking
SET status = 'CANCELLED'
WHERE id = #{id}
AND user_id = #{userId}
AND status = 'BOOKED'

